import { mkdir, rm, writeFile, readFile } from 'node:fs/promises';
import { dirname } from 'node:path';
import { execFile } from 'node:child_process';
import { promisify } from 'node:util';

const execFileAsync = promisify(execFile);
const files = {"dist/app.js":"","dist/assets/brand-lockup.png":"","dist/assets/brand-mark.png":"","dist/assets/hero-city.jpg":"","dist/data/municipality-official-services.json":"","dist/index.html":"","dist/manifest.webmanifest":"","dist/styles.css":"","netlify/functions/analyze.mjs":"","netlify/functions/health.mjs":"","netlify/functions/lib/analysis-core.mjs":"","netlify/functions/lib/environment-client.mjs":"","netlify/functions/lib/geo.mjs":"","netlify/functions/lib/http.mjs":"","netlify/functions/lib/municipality-catalog.mjs":"","netlify/functions/lib/municipality-provider.mjs":"","netlify/functions/lib/plan-context-client.mjs":"","netlify/functions/lib/tkgm-api.mjs":"","netlify/functions/lib/tkgm-client.mjs":"","netlify/functions/lib/zoning-client.mjs":"","netlify/functions/official-services.mjs":"","netlify/functions/request-analysis.mjs":"","netlify/functions/tkgm.mjs":"","netlify/functions/user-data.mjs":""};

await rm('dist', { recursive: true, force: true });
await rm('netlify/functions', { recursive: true, force: true });

for (const [path, encoded] of Object.entries(files)) {
  await mkdir(dirname(path), { recursive: true });
  await writeFile(path, Buffer.from(encoded, 'base64'));
}

const syntaxChecks = ["dist/app.js", "netlify/functions/analyze.mjs", "netlify/functions/health.mjs", "netlify/functions/lib/analysis-core.mjs", "netlify/functions/lib/environment-client.mjs", "netlify/functions/lib/geo.mjs", "netlify/functions/lib/http.mjs", "netlify/functions/lib/municipality-catalog.mjs", "netlify/functions/lib/municipality-provider.mjs", "netlify/functions/lib/plan-context-client.mjs", "netlify/functions/lib/tkgm-api.mjs", "netlify/functions/lib/tkgm-client.mjs", "netlify/functions/lib/zoning-client.mjs", "netlify/functions/official-services.mjs", "netlify/functions/request-analysis.mjs", "netlify/functions/tkgm.mjs", "netlify/functions/user-data.mjs"];
for (const path of syntaxChecks) await execFileAsync(process.execPath, ['--check', path]);

const [html, app, health, provider, catalogModule, catalogJson, netlifyConfig] = await Promise.all([
  readFile('dist/index.html', 'utf8'),
  readFile('dist/app.js', 'utf8'),
  readFile('netlify/functions/health.mjs', 'utf8'),
  readFile('netlify/functions/lib/municipality-provider.mjs', 'utf8'),
  readFile('netlify/functions/lib/municipality-catalog.mjs', 'utf8'),
  readFile('dist/data/municipality-official-services.json', 'utf8'),
  readFile('netlify.toml', 'utf8')
]);

const catalog = JSON.parse(catalogJson);
if (catalog?.stats?.recordCount !== 117) throw new Error('Gömülü katalog 117 kayıt içermiyor.');
if (!catalog.records?.some((item) => item.authority === 'Şişli Belediyesi')) throw new Error('Şişli Belediyesi katalog kaydı eksik.');
if (!catalog.records?.some((item) => item.authority === 'Keçiören Belediyesi')) throw new Error('Çoklu hizmet test kaydı eksik.');

const requiredMarkers = [
  'planlamasyon-theme-v3-1-3', 'planlamasyon-netlify-v3.1.3', 'Gömülü katalog',
  'MUNICIPALITY_CATALOG', 'matchEmbeddedCatalog', 'embeddedMunicipalityCatalogRecords',
  '/api/official-services', 'municipality-geodata', 'official-login-service',
  '/api/analyze', '/api/request-analysis', 'e-plan.gov.tr', 'ucbp.tucbs.gov.tr'
];
const combined = [html, app, health, provider, catalogModule, netlifyConfig].join('\n');
for (const marker of requiredMarkers) if (!combined.includes(marker)) throw new Error(`Eksik build işareti: ${marker}`);
if (/Bilgi 1|Bilgi 2|loadingRows/.test(app + html)) throw new Error('Eski sahte yükleme satırları temizlenmedi.');
if (app.includes('0 / 0')) throw new Error('Eksik TAKS/Emsal 0 / 0 gösteriliyor.');
if (combined.includes('prefers-color-scheme')) throw new Error('Tema cihaz temasına bağlı olmamalıdır.');
if (combined.includes('planlamasyon-netlify-v3.1.2')) throw new Error('Eski v3.1.2 kalıntısı bulundu.');

console.log(`Planlamasyon v3.1.3 build tamamlandı: ${Object.keys(files).length} dosya ve ${catalog.stats.recordCount} katalog kaydı üretildi.`);
